43	    pub fn commutative_pair<'x, A, F, G, RetF: 'x, RetG: 'x>(
44	        pair: (&'x A, &'x A),
45	        check_a: F,
46	        check_b: G,
47	    ) -> Option<(RetF, RetG)>
48	    where
49	        F: Fn(&'x A) -> Option<RetF>,
50	        G: Fn(&'x A) -> Option<RetG>,
51	    {
52	        match check_a(pair.0) {
53	            Some(a) => {
54	                if let Some(b) = check_b(pair.1) {
55	                    return Some((a, b));
56	                }
57	            }
58	            _ => {
59	                if let Some(a) = check_a(pair.1)
60	                    && let Some(b) = check_b(pair.0)
61	                {
62	                    return Some((a, b));
63	                }
64	            }
65	        }
66	        None
67	    }
