127	    /// Refresh `ScopeFlags::DirectEval` from live direct-eval call sites.
128	    ///
129	    /// `direct_eval_scopes` lists scopes that still contain a direct `eval(...)` call.
130	    /// Clears `DirectEval` from every scope, then re-propagates from each scope in the
131	    /// set up to the root.
132	    ///
133	    /// Skipping this leaves `DirectEval` set on scopes whose only eval call was just
134	    /// DCE'd, which keeps unused-declaration removal conservative until reparse.
135	    fn refresh_direct_eval_flags(scoping: &mut Scoping, direct_eval_scopes: &FxHashSet<ScopeId>) {
136	        // Semantic propagates `DirectEval` to the root, so an empty live set plus a
137	        // clean root means no scope has the flag — nothing to clear or set.
138	        if direct_eval_scopes.is_empty() && !scoping.root_scope_flags().contains_direct_eval() {
139	            return;
140	        }
141	
142	        for index in 0..scoping.scopes_len() {
143	            scoping.scope_flags_mut(ScopeId::from_usize(index)).remove(ScopeFlags::DirectEval);
144	        }
145	
146	        for &scope_id in direct_eval_scopes {
147	            let mut ancestor = Some(scope_id);
148	            while let Some(scope_id) = ancestor {
149	                let flags = scoping.scope_flags_mut(scope_id);
150	                // An earlier iteration already flagged this chain; stop walking up.
151	                if flags.contains_direct_eval() {
