        "var re = new WeakMap(); x = new Set(re)",
        "var re = new Map(); x = new Set(re)",
    ] {
        let first = run(src);
        let second = run(&first);
        println!("SRC:    {src}");
        println!("FIRST:  {first}");
        println!("SECOND: {second}");
        println!("idempotent = {}\n", first == second);
    }
}
